def test_prop_add_is_commutative():
    """Property: add(a, b) == add(b, a) for all finite floats."""
    @given(st.floats(allow_nan=False, allow_infinity=False),
           st.floats(allow_nan=False, allow_infinity=False))
    @settings(max_examples=200)
    def _inner(a, b):
        assert add(a, b) == pytest.approx(add(b, a), rel=1e-9, abs=1e-12)
    _inner()
